package com.primehr.performancemanagement.application;

import com.primehr.integration.administrative.PermissionDataScope;import com.primehr.performancemanagement.api.PerformanceCoachingDtos.*;import com.primehr.performancemanagement.domain.*;import com.primehr.performancemanagement.infrastructure.*;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;

@Service@Transactional public class PerformanceCoachingServiceImpl implements PerformanceCoachingService{
 private final PerformanceMonitoringCaseRepository cases;private final PerformanceCoachingSessionRepository sessions;private final PerformanceCoachingSessionItemRepository sessionItems;private final PerformanceCoachingActionItemRepository actionItems;private final PerformanceMidCycleReviewRepository reviews;private final PerformanceCommitmentItemRepository commitmentItems;private final PerformanceMonitoringUpdateRepository updates;private final PerformanceMonitoringEvidenceRepository evidence;private final PerformanceMonitoringActionRepository actions;private final PerformancePolicyVersionRepository policies;private final PerformanceCycleMilestoneRepository milestones;private final PerformanceManagementTeamMemberRepository pmtMembers;private final PrimeHrAuditService audit;
 public PerformanceCoachingServiceImpl(PerformanceMonitoringCaseRepository c,PerformanceCoachingSessionRepository s,PerformanceCoachingSessionItemRepository si,PerformanceCoachingActionItemRepository ai,PerformanceMidCycleReviewRepository r,PerformanceCommitmentItemRepository ci,PerformanceMonitoringUpdateRepository u,PerformanceMonitoringEvidenceRepository e,PerformanceMonitoringActionRepository a,PerformancePolicyVersionRepository p,PerformanceCycleMilestoneRepository m,PerformanceManagementTeamMemberRepository pm,PrimeHrAuditService au){cases=c;sessions=s;sessionItems=si;actionItems=ai;reviews=r;commitmentItems=ci;updates=u;evidence=e;actions=a;policies=p;milestones=m;pmtMembers=pm;audit=au;}
 @Override@Transactional(readOnly=true)public List<SessionResponse>sessions(String agency,String caseId,String actor,PermissionDataScope scope){var c=monitoringCase(agency,caseId);access(c,actor,scope);return sessions.findByAgencyIdAndMonitoringCaseIdOrderBySessionAtAsc(agency,caseId).stream().map(x->response(agency,x,privateVisible(c,actor,scope))).toList();}
 @Override public SessionResponse createSession(String agency,String caseId,SessionInput in,String actor,PermissionDataScope scope,String correlation){var c=monitoringCase(agency,caseId);supervisor(c,actor,scope);active(c);var prior=action(agency,caseId,in.idempotencyKey());if(prior!=null)return response(agency,session(agency,prior.getSubjectId()),true);validateItems(agency,c,in.commitmentItemIds());var value=sessions.saveAndFlush(new PerformanceCoachingSession(agency,caseId,UUID.randomUUID().toString(),1,null,in.sessionAt(),in.agenda(),in.goal(),in.observedIssue(),in.agreedAction(),in.resourcesSupport(),in.actionDueDate(),in.nextMeetingAt(),in.employeeVisibleFeedback(),in.privateNotes()));for(String item:distinct(in.commitmentItemIds()))sessionItems.save(new PerformanceCoachingSessionItem(agency,value.getId(),item));record(agency,caseId,value.getId(),"CREATE_COACHING_SESSION",in.idempotencyKey(),actor,null);var after=response(agency,value,true);audit.record(agency,"CREATE_COACHING_SESSION","SPMS_COACHING_SESSION",value.getId(),1,value.getVersion(),null,after,null,correlation);return after;}
 @Override public SessionResponse editSession(String agency,String id,SessionEdit in,String actor,PermissionDataScope scope,String correlation){var value=session(agency,id);var c=monitoringCase(agency,value.getMonitoringCaseId());supervisor(c,actor,scope);active(c);check(value.getVersion(),in.recordVersion());var before=response(agency,value,true);value.edit(in.sessionAt(),in.agenda(),in.goal(),in.observedIssue(),in.agreedAction(),in.resourcesSupport(),in.actionDueDate(),in.nextMeetingAt(),in.employeeVisibleFeedback(),in.privateNotes());value=sessions.saveAndFlush(value);var after=response(agency,value,true);audit.record(agency,"EDIT_COACHING_SESSION","SPMS_COACHING_SESSION",id,value.getRevisionNo(),value.getVersion(),before,after,null,correlation);return after;}
 @Override public SessionResponse transitionSession(String agency,String id,SessionAction in,String actor,PermissionDataScope scope,String action,String correlation){var value=session(agency,id);var c=monitoringCase(agency,value.getMonitoringCaseId());if("ACKNOWLEDGE".equals(action))owner(c,actor,scope);else supervisor(c,actor,scope);if(this.action(agency,c.getId(),in.idempotencyKey())!=null)return response(agency,value,privateVisible(c,actor,scope));active(c);check(value.getVersion(),in.recordVersion());var before=response(agency,value,true);switch(action){case"ISSUE"->value.issue(actor,Instant.now());case"ACKNOWLEDGE"->value.acknowledge(actor,in.employeeResponse(),Instant.now());case"VOID"->value.voided(in.reason());default->throw new IllegalArgumentException("Unsupported coaching action");}value=sessions.saveAndFlush(value);record(agency,c.getId(),id,action+"_COACHING_SESSION",in.idempotencyKey(),actor,in.reason());var after=response(agency,value,privateVisible(c,actor,scope));audit.record(agency,action+"_COACHING_SESSION","SPMS_COACHING_SESSION",id,value.getRevisionNo(),value.getVersion(),before,after,in.reason(),correlation);return after;}
 @Override public SessionResponse correctSession(String agency,String id,SessionInput in,String actor,PermissionDataScope scope,String correlation){var prior=session(agency,id);var c=monitoringCase(agency,prior.getMonitoringCaseId());supervisor(c,actor,scope);active(c);var recorded=action(agency,c.getId(),in.idempotencyKey());if(recorded!=null)return response(agency,session(agency,recorded.getSubjectId()),true);if(prior.getStatus()!=PerformanceCoachingSession.Status.ISSUED&&prior.getStatus()!=PerformanceCoachingSession.Status.ACKNOWLEDGED)throw new IllegalStateException("Only issued coaching history may be corrected");validateItems(agency,c,in.commitmentItemIds());int revision=sessions.findByAgencyIdAndRootSessionIdOrderByRevisionNoAsc(agency,prior.getRootSessionId()).stream().mapToInt(PerformanceCoachingSession::getRevisionNo).max().orElse(0)+1;prior.supersede();sessions.saveAndFlush(prior);var value=sessions.saveAndFlush(new PerformanceCoachingSession(agency,c.getId(),prior.getRootSessionId(),revision,prior.getId(),in.sessionAt(),in.agenda(),in.goal(),in.observedIssue(),in.agreedAction(),in.resourcesSupport(),in.actionDueDate(),in.nextMeetingAt(),in.employeeVisibleFeedback(),in.privateNotes()));for(String item:distinct(in.commitmentItemIds()))sessionItems.save(new PerformanceCoachingSessionItem(agency,value.getId(),item));record(agency,c.getId(),value.getId(),"CORRECT_COACHING_SESSION",in.idempotencyKey(),actor,null);var after=response(agency,value,true);audit.record(agency,"CORRECT_COACHING_SESSION","SPMS_COACHING_SESSION",value.getId(),revision,value.getVersion(),null,after,null,correlation);return after;}
 @Override public ActionItemResponse addActionItem(String agency,String sessionId,ActionItemInput in,String actor,PermissionDataScope scope,String correlation){var session=session(agency,sessionId);var c=monitoringCase(agency,session.getMonitoringCaseId());supervisor(c,actor,scope);active(c);if(session.getStatus()==PerformanceCoachingSession.Status.VOIDED||session.getStatus()==PerformanceCoachingSession.Status.SUPERSEDED)throw new IllegalStateException("Coaching session cannot receive action items");var prior=action(agency,c.getId(),in.idempotencyKey());if(prior!=null)return actionResponse(actionItem(agency,prior.getSubjectId()));if(!Set.of(c.getOwnerEmployeeNo().toUpperCase(Locale.ROOT),c.getSupervisorEmployeeNo().toUpperCase(Locale.ROOT)).contains(in.accountableEmployeeNo().toUpperCase(Locale.ROOT)))throw new IllegalArgumentException("Accountable employee must be the monitoring owner or assigned supervisor");var value=actionItems.saveAndFlush(new PerformanceCoachingActionItem(agency,c.getId(),sessionId,in.description(),in.accountableEmployeeNo(),in.dueDate()));record(agency,c.getId(),value.getId(),"CREATE_COACHING_ACTION_ITEM",in.idempotencyKey(),actor,null);var after=actionResponse(value);audit.record(agency,"CREATE_COACHING_ACTION_ITEM","SPMS_COACHING_ACTION_ITEM",value.getId(),null,value.getVersion(),null,after,null,correlation);return after;}
 @Override public ActionItemResponse updateActionItem(String agency,String id,ActionItemEdit in,String actor,PermissionDataScope scope,String correlation){var value=actionItem(agency,id);var c=monitoringCase(agency,value.getMonitoringCaseId());access(c,actor,scope);if(scope!=PermissionDataScope.AGENCY_WIDE&&!value.getAccountableEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the accountable employee may update this action item");if(action(agency,c.getId(),in.idempotencyKey())!=null)return actionResponse(value);active(c);check(value.getVersion(),in.recordVersion());var before=actionResponse(value);value.progress(in.progressNote(),in.completed(),Instant.now());value=actionItems.saveAndFlush(value);record(agency,c.getId(),id,"UPDATE_COACHING_ACTION_ITEM",in.idempotencyKey(),actor,null);var after=actionResponse(value);audit.record(agency,"UPDATE_COACHING_ACTION_ITEM","SPMS_COACHING_ACTION_ITEM",id,null,value.getVersion(),before,after,null,correlation);return after;}
 @Override public ActionItemResponse decideActionItem(String agency,String id,SessionAction in,String actor,PermissionDataScope scope,boolean verify,String correlation){var value=actionItem(agency,id);var c=monitoringCase(agency,value.getMonitoringCaseId());supervisor(c,actor,scope);if(action(agency,c.getId(),in.idempotencyKey())!=null)return actionResponse(value);active(c);check(value.getVersion(),in.recordVersion());var before=actionResponse(value);if(verify)value.verify(actor,Instant.now());else value.reopen(in.reason());value=actionItems.saveAndFlush(value);record(agency,c.getId(),id,verify?"VERIFY_COACHING_ACTION_ITEM":"REOPEN_COACHING_ACTION_ITEM",in.idempotencyKey(),actor,in.reason());var after=actionResponse(value);audit.record(agency,verify?"VERIFY_COACHING_ACTION_ITEM":"REOPEN_COACHING_ACTION_ITEM","SPMS_COACHING_ACTION_ITEM",id,null,value.getVersion(),before,after,in.reason(),correlation);return after;}
 @Override@Transactional(readOnly=true)public ReviewResponse getReview(String agency,String caseId,String actor,PermissionDataScope scope){var c=monitoringCase(agency,caseId);access(c,actor,scope);return reviewResponse(reviews.findByAgencyIdAndMonitoringCaseId(agency,caseId).orElseThrow(()->new ResourceNotFoundException("Mid-cycle review not found")));}
 @Override public ReviewResponse createReview(String agency,String caseId,ReviewInput in,String actor,PermissionDataScope scope,String correlation){var c=monitoringCase(agency,caseId);supervisor(c,actor,scope);active(c);requireMidCycle(agency,c);var prior=action(agency,caseId,in.idempotencyKey());if(prior!=null)return reviewResponse(review(agency,prior.getSubjectId()));if(reviews.findByAgencyIdAndMonitoringCaseId(agency,caseId).isPresent())throw new IllegalArgumentException("A mid-cycle review already exists for this monitoring case");int updateCount=updates.findByAgencyIdAndMonitoringCaseIdOrderByCreatedAtAsc(agency,caseId).size();int open=(int)actionItems.findByAgencyIdAndMonitoringCaseIdOrderByDueDateAsc(agency,caseId).stream().filter(x->x.getStatus()!=PerformanceCoachingActionItem.Status.COMPLETED&&x.getStatus()!=PerformanceCoachingActionItem.Status.CANCELLED).count();int missing=missingEvidence(agency,c);var value=reviews.saveAndFlush(new PerformanceMidCycleReview(agency,caseId,updateCount,open,missing,in.supervisorNarrative(),in.employeeNarrative(),in.amendmentRecommended(),in.amendmentReason()));record(agency,caseId,value.getId(),"CREATE_MID_CYCLE_REVIEW",in.idempotencyKey(),actor,null);var after=reviewResponse(value);audit.record(agency,"CREATE_MID_CYCLE_REVIEW","SPMS_MID_CYCLE_REVIEW",value.getId(),null,value.getVersion(),null,after,null,correlation);return after;}
 @Override public ReviewResponse editReview(String agency,String id,ReviewEdit in,String actor,PermissionDataScope scope,String correlation){var value=review(agency,id);var c=monitoringCase(agency,value.getMonitoringCaseId());supervisor(c,actor,scope);active(c);check(value.getVersion(),in.recordVersion());var before=reviewResponse(value);value.edit(in.supervisorNarrative(),in.employeeNarrative(),in.amendmentRecommended(),in.amendmentReason());value=reviews.saveAndFlush(value);var after=reviewResponse(value);audit.record(agency,"EDIT_MID_CYCLE_REVIEW","SPMS_MID_CYCLE_REVIEW",id,null,value.getVersion(),before,after,null,correlation);return after;}
 @Override public ReviewResponse transitionReview(String agency,String id,ReviewAction in,String actor,PermissionDataScope scope,String action,String correlation){var value=review(agency,id);var c=monitoringCase(agency,value.getMonitoringCaseId());if("ACKNOWLEDGE".equals(action))owner(c,actor,scope);else if("CLOSE_WITHOUT_ACKNOWLEDGMENT".equals(action)){if(scope!=PermissionDataScope.AGENCY_WIDE||!isPmt(agency,actor))throw new AccessDeniedException("Closing without acknowledgment requires agency-wide PMT authority");}else supervisor(c,actor,scope);if(this.action(agency,c.getId(),in.idempotencyKey())!=null)return reviewResponse(value);active(c);check(value.getVersion(),in.recordVersion());var before=reviewResponse(value);switch(action){case"SUBMIT"->value.submit(actor,Instant.now());case"ACKNOWLEDGE"->value.acknowledge(actor,in.employeeNarrative(),Instant.now());case"CLOSE_WITHOUT_ACKNOWLEDGMENT"->value.closeWithoutAcknowledgment(in.reason());default->throw new IllegalArgumentException("Unsupported mid-cycle action");}value=reviews.saveAndFlush(value);record(agency,c.getId(),id,action+"_MID_CYCLE_REVIEW",in.idempotencyKey(),actor,in.reason());var after=reviewResponse(value);audit.record(agency,action+"_MID_CYCLE_REVIEW","SPMS_MID_CYCLE_REVIEW",id,null,value.getVersion(),before,after,in.reason(),correlation);return after;}
 private void requireMidCycle(String agency,PerformanceMonitoringCase c){var p=policies.findByIdAndAgencyId(c.getPolicyVersionId(),agency).orElseThrow(()->new ResourceNotFoundException("Performance policy version not found"));if(!p.isRequiresMidCycleReview())throw new IllegalArgumentException("The exact policy version does not require a mid-cycle review");var milestone=milestones.findByAgencyIdAndCycleIdOrderByDisplayOrderAsc(agency,c.getCycleId()).stream().filter(x->x.getType()==PerformanceCycleMilestone.Type.MID_CYCLE_REVIEW).findFirst().orElseThrow(()->new IllegalArgumentException("MID_CYCLE_REVIEW milestone is required"));Instant now=Instant.now(),end=milestone.getEndsAt()==null?milestone.getStartsAt():milestone.getEndsAt();if(now.isBefore(milestone.getStartsAt())||now.isAfter(end))throw new IllegalArgumentException("Mid-cycle review is outside the configured cycle window");}
 private int missingEvidence(String agency,PerformanceMonitoringCase c){var required=commitmentItems.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(agency,c.getCommitmentVersionId()).stream().filter(x->x.isRequired()&&x.isSourceRequiresEvidence()).toList();var present=evidence.findByAgencyIdAndMonitoringCaseIdOrderByUploadedAtAsc(agency,c.getId());return(int)required.stream().filter(i->present.stream().noneMatch(e->e.getCommitmentItemId().equals(i.getId())&&e.getStatus()==PerformanceMonitoringEvidence.Status.ACTIVE)).count();}
 private void validateItems(String agency,PerformanceMonitoringCase c,List<String>ids){for(String id:distinct(ids))commitmentItems.findById(id).filter(x->x.getAgencyId().equals(agency)&&x.getCommitmentVersionId().equals(c.getCommitmentVersionId())).orElseThrow(()->new ResourceNotFoundException("Commitment item not found in monitoring case"));}private static List<String>distinct(List<String>ids){return ids==null?List.of():ids.stream().filter(Objects::nonNull).distinct().toList();}
 private SessionResponse response(String agency,PerformanceCoachingSession s,boolean privateNotes){var ids=sessionItems.findByAgencyIdAndCoachingSessionId(agency,s.getId()).stream().map(PerformanceCoachingSessionItem::getCommitmentItemId).toList();var ai=actionItems.findByAgencyIdAndCoachingSessionIdOrderByDueDateAsc(agency,s.getId()).stream().map(this::actionResponse).toList();return new SessionResponse(s.getId(),s.getMonitoringCaseId(),s.getRootSessionId(),s.getRevisionNo(),s.getSupersedesId(),s.getSessionAt(),s.getAgenda(),s.getGoal(),s.getObservedIssue(),s.getAgreedAction(),s.getResourcesSupport(),s.getActionDueDate(),s.getNextMeetingAt(),s.getEmployeeVisibleFeedback(),privateNotes?s.getPrivateNotes():null,s.getEmployeeResponse(),s.getStatus().name(),s.getIssuedBy(),s.getIssuedAt(),s.getAcknowledgedBy(),s.getAcknowledgedAt(),s.getVoidReason(),s.getVersion(),ids,ai);}
 private ActionItemResponse actionResponse(PerformanceCoachingActionItem v){return new ActionItemResponse(v.getId(),v.getCoachingSessionId(),v.getDescription(),v.getAccountableEmployeeNo(),v.getDueDate(),v.getStatus().name(),v.getProgressNote(),v.getCompletedAt(),v.getVerifiedBy(),v.getVerifiedAt(),v.getReopenReason(),v.getVersion());}private ReviewResponse reviewResponse(PerformanceMidCycleReview v){return new ReviewResponse(v.getId(),v.getMonitoringCaseId(),v.getSnapshotUpdateCount(),v.getSnapshotOpenActionCount(),v.getSnapshotMissingEvidenceCount(),v.getSupervisorNarrative(),v.getEmployeeNarrative(),v.isAmendmentRecommended(),v.getAmendmentReason(),v.getStatus().name(),v.getSubmittedBy(),v.getSubmittedAt(),v.getAcknowledgedBy(),v.getAcknowledgedAt(),v.getClosureReason(),v.getVersion());}
 private void active(PerformanceMonitoringCase c){if(c.getStatus()==PerformanceMonitoringCase.Status.VOIDED||c.getStatus()==PerformanceMonitoringCase.Status.READY_FOR_RATING)throw new IllegalStateException("Monitoring case is closed for coaching");}private void owner(PerformanceMonitoringCase c,String actor,PermissionDataScope scope){if(!c.getOwnerEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the monitoring owner may perform this action");}private void supervisor(PerformanceMonitoringCase c,String actor,PermissionDataScope scope){if(!c.getSupervisorEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the assigned supervisor may perform this action");}private boolean visible(PerformanceMonitoringCase c,String actor,PermissionDataScope scope){return scope==PermissionDataScope.OWN_RECORDS&&c.getOwnerEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.ASSIGNED_RECORDS&&c.getSupervisorEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.AGENCY_WIDE&&(c.getOwnerEmployeeNo().equalsIgnoreCase(actor)||c.getSupervisorEmployeeNo().equalsIgnoreCase(actor)||isPmt(c.getAgencyId(),actor));}private void access(PerformanceMonitoringCase c,String actor,PermissionDataScope scope){if(!visible(c,actor,scope))throw new AccessDeniedException("Coaching record is outside the permitted scope");}private boolean privateVisible(PerformanceMonitoringCase c,String actor,PermissionDataScope scope){return c.getSupervisorEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.AGENCY_WIDE&&isPmt(c.getAgencyId(),actor);}private boolean isPmt(String agency,String actor){return pmtMembers.isEffectiveMember(agency,actor,LocalDate.now(ZoneId.of("Asia/Manila")));}
 private PerformanceMonitoringCase monitoringCase(String a,String id){return cases.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance monitoring case not found"));}private PerformanceCoachingSession session(String a,String id){return sessions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Coaching session not found"));}private PerformanceCoachingActionItem actionItem(String a,String id){return actionItems.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Coaching action item not found"));}private PerformanceMidCycleReview review(String a,String id){return reviews.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Mid-cycle review not found"));}private PerformanceMonitoringAction action(String a,String c,String key){return actions.findByAgencyIdAndMonitoringCaseIdAndRequestKey(a,c,key).orElse(null);}private void record(String a,String c,String subject,String type,String key,String actor,String reason){actions.saveAndFlush(new PerformanceMonitoringAction(a,c,subject,type,key,actor,reason,Instant.now()));}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Expected recordVersion "+expected+" but current version is "+actual);}
}
